WITH spine_months AS (SELECT DISTINCT CAST(date_trunc('month', date_day) AS DATE) AS month_start FROM {{ ref('time_spine') }}), eligible_account_month AS (SELECT DISTINCT c.member_id, s.month_start FROM {{ ref('cards') }} c INNER JOIN spine_months s ON c.card_type IN ('悦享年卡', '家庭季卡') AND c.valid_from IS NOT NULL AND c.valid_until IS NOT NULL AND c.valid_from < c.valid_until AND (c.ended_at IS NULL OR (c.ended_at > c.valid_from AND c.ended_at < c.valid_until)) AND c.valid_from <= last_day(s.month_start) AND last_day(s.month_start) < c.valid_until AND (c.ended_at IS NULL OR last_day(s.month_start) < c.ended_at)), account_month_orders AS (SELECT o.member_id, CAST(date_trunc('month', o.ordered_at) AS DATE) AS month_start, COUNT(DISTINCT o.order_id) AS valid_order_count, SUM(o.paid_cents - o.refund_cents) AS net_sales_cents FROM {{ ref('orders') }} o WHERE o.status = 'paid' AND o.paid_cents - o.refund_cents > 0 GROUP BY o.member_id, CAST(date_trunc('month', o.ordered_at) AS DATE)), qualified_account_month AS (SELECT e.member_id, e.month_start, o.valid_order_count, o.net_sales_cents FROM eligible_account_month e INNER JOIN account_month_orders o ON e.member_id = o.member_id AND e.month_start = o.month_start), monthly_agg AS (SELECT month_start, COUNT(DISTINCT member_id) AS paid_buyer_count, SUM(valid_order_count) AS paid_order_count, SUM(net_sales_cents) AS paid_sales_cents, COUNT(DISTINCT CASE WHEN valid_order_count >= 2 THEN member_id END) AS paid_repeat_buyer_count FROM qualified_account_month GROUP BY month_start) SELECT s.month_start, COALESCE(a.paid_buyer_count, 0) AS paid_buyer_count, COALESCE(a.paid_order_count, 0) AS paid_order_count, COALESCE(a.paid_sales_cents, 0) AS paid_sales_cents, COALESCE(a.paid_repeat_buyer_count, 0) AS paid_repeat_buyer_count FROM spine_months s LEFT JOIN monthly_agg a ON s.month_start = a.month_start